// cards_wishlist.js — данные для игры "Совместный плейлист желаний"
// Каждый партнёр по очереди и наедине отмечает "Да"/"Нет" по каждому пункту.
// В конце показываются только совпавшие "Да" — то, что хотят попробовать оба.
// У каждого пункта есть краткий заголовок (text) и развёрнутое, изящное
// пояснение (desc) — экран прокручивается, если карточка не влезает целиком,
// поэтому desc может быть заметно длиннее заголовка, но не в целый абзац.

const WISHLIST_ITEMS = [
  { text: 'Ролевые игры', desc: 'Выберите роли, придумайте общий сюжет и заранее обсудите границы игры. На один вечер можно стать незнакомцами, героями фильма или персонажами собственной истории, сохраняя возможность остановиться в любой момент.' },
  { text: 'Секс-игрушки', desc: 'Выберите интимную игрушку вместе, изучите инструкцию и заранее договоритесь о способе использования. Игрушка должна быть дополнением к близости, а не обязательным условием или заменой партнёру.' },
  { text: 'Эротический массаж', desc: 'Начните с обычного расслабляющего массажа и постепенно переходите к более чувственным прикосновениям, ориентируясь на реакцию партнёра. Используйте подходящее масло или лубрикант и остановитесь при дискомфорте.' },
  { text: 'Секс при свете', desc: 'Оставьте свет включённым и позвольте себе видеть выражение лица, движения и реакцию партнёра. Выберите освещение, при котором обоим комфортно, и не превращайте открытость в обязанность.' },
  { text: 'Секс в душе или ванной', desc: 'Перенесите близость в ванную, заранее проверьте температуру воды, наличие устойчивой опоры и нескользящего коврика. Вода не заменяет лубрикант, а безопасность важнее необычной позы.' },
  { text: 'Лёгкое связывание руками', desc: 'Используйте мягкие фиксаторы или шарф для непродолжительного ограничения движений только после согласия обоих. Не затягивайте материал, держите способ быстрого освобождения рядом и заранее выберите стоп-сигнал.' },
  { text: 'Повязка на глаза', desc: 'Закройте партнёру глаза мягкой повязкой и заранее договоритесь о допустимых прикосновениях и сигнале остановки. Отсутствие зрения может усилить внимание к звукам и ощущениям, но партнёр должен чувствовать себя безопасно.' },
  { text: 'Дразнящие игры без быстрого финала', desc: 'Договоритесь не торопиться к оргазму и чередуйте лёгкие прикосновения, поцелуи, паузы и изменение темпа. Целью может быть само предвкушение, а не обязательное завершение.' },
  { text: 'Секс на кухне', desc: 'Выберите устойчивое и безопасное место на кухне, уберите горячие, острые и хрупкие предметы, а затем перенесите туда привычную близость. Новая обстановка не должна создавать риск травмы или помехи другим людям.' },
  { text: 'Секс в машине', desc: 'Уединитесь в припаркованной машине только на разрешённой частной территории, где вас никто не увидит и не потревожит. Поставьте автомобиль на ручник, выключите двигатель и заранее освободите достаточно места в салоне.' },
  { text: 'Ролевая игра «незнакомцы»', desc: 'Придумайте новые имена и представьте, что встречаетесь впервые. Разыграйте знакомство, разговор и флирт, заранее договорившись, какие действия остаются только частью игры.' },
  { text: 'Риск быть услышанными', desc: 'Если хочется добавить волнения, выберите полностью приватное помещение и безопасный уровень громкости. Никто посторонний не должен быть вынужден слышать происходящее, а любой партнёр может попросить говорить тише.' },
  { text: 'Совместный просмотр эротики', desc: 'Выберите контент, который подходит обоим, и заранее обсудите, что просмотр не создаёт обязательства повторять увиденное. Используйте его как повод поговорить о желаниях, а не как инструкцию или стандарт.' },
  { text: 'Долгие оральные ласки', desc: 'Посвятите оральным ласкам достаточно времени, не торопясь к финалу и регулярно ориентируясь на реакцию партнёра. Обсудите комфортный темп, паузы и предпочтительный способ завершения.' },
  { text: 'Утренний секс', desc: 'Начните день с поцелуев, объятий и близости после того, как оба проснулись и готовы продолжать. Не торопитесь и учитывайте, что утреннее настроение и самочувствие у партнёров могут различаться.' },
  { text: 'Секс со свечами и музыкой', desc: 'Подготовьте спокойный плейлист и мягкое освещение, разместив свечи на устойчивых поверхностях вдали от ткани. Атмосфера должна помогать расслабиться, а не создавать риск пожара или дискомфорт от запаха.' },
  { text: 'Ролевая игра «доставка/сервис»', desc: 'Разыграйте встречу у двери: один партнёр приходит как курьер или мастер, а второй встречает его как клиент. Заранее выберите роли, реплики и границы, чтобы бытовой сюжет оставался добровольной игрой.' },
  { text: 'Лёгкое доминирование одного партнёра', desc: 'Один партнёр временно ведёт сценарий, выбирает темп и предлагает действия, а второй добровольно следует договорённостям. До начала обсудите границы, стоп-слово и возможность остановиться без объяснений.' },
  { text: 'Лёгкое подчинение по очереди', desc: 'Партнёры по очереди меняются ролями ведущего и ведомого, заранее определяя допустимые команды и действия. Подчинение в игре всегда добровольно и не переносится на повседневные отношения.' },
  { text: 'Секс в отпуске или другом городе', desc: 'Используйте новую обстановку как возможность провести больше времени вдвоём, но заранее позаботьтесь о приватности, безопасности и комфортном месте. Путешествие создаёт атмосферу, но не обязывает к близости.' },
  { text: 'Эротическая переписка в течение дня', desc: 'Обменивайтесь флиртующими сообщениями в течение дня, обсуждая только те темы и изображения, которые комфортны обоим. Помните о приватности переписки и не отправляйте материалы без согласия партнёра.' },
  { text: 'Стриптиз друг для друга', desc: 'Включите музыку и по очереди исполняйте медленный танец с постепенным снятием одежды. Каждый сам выбирает, сколько одежды снять и когда остановиться.' },
  { text: 'Секс перед зеркалом', desc: 'Выберите устойчивое зеркало в приватном месте и наблюдайте за собой и партнёром во время близости. Зрительный контакт и отражение должны быть приятными, а не превращаться в источник стеснения или оценки.' },
  { text: 'Долгая прелюдия (30+ минут)', desc: 'Выделите не менее получаса на поцелуи, массаж, прикосновения и другие ласки без обязательного перехода к проникновению. Делайте паузы и меняйте темп по реакции обоих.' },
  { text: 'Новая поза раз в неделю', desc: 'Раз в неделю выбирайте одну новую позу, заранее обсуждайте её удобство и пробуйте без ожидания идеального результата. Остановитесь при боли, потере равновесия или нежелании продолжать.' },
  { text: 'Секс без ограничения по времени в выходной', desc: 'Освободите часть выходного дня от дел и не торопитесь завершать близость. Можно делать перерывы на отдых, воду, разговор и возвращаться к ласкам только при желании обоих.' },
  { text: 'Совместный шопинг за бельём', desc: 'Выберите бельё вместе, учитывая размер, удобство и желание того, кто будет его носить. Покупка должна быть совместным флиртом, а не требованием надеть или снять конкретную вещь.' },
  { text: 'Секс на природе', desc: 'Выберите разрешённое и полностью приватное место на частной территории, где вас не увидят посторонние. Проверьте погоду, связь, тёплые вещи, гигиену и возможность безопасно уйти.' },
  { text: 'Романтический уикенд с акцентом на близость', desc: 'Запланируйте выходные с минимумом бытовых дел и максимумом времени друг для друга. Заранее обсудите ожидания, бюджет, отдых и право каждого изменить планы из-за усталости или самочувствия.' },
  { text: 'Лёд или тёплое масло в ласках', desc: 'Используйте краткий контакт с кубиком льда и подходящим тёплым массажным маслом для контраста ощущений. Сначала проверьте температуру на небольшом участке кожи и не наносите масла на слизистые или латекс.' },
  { text: 'Ролевая игра «учитель и ученик»', desc: 'Совершеннолетние партнёры разыгрывают учебный сценарий с заранее выбранными ролями, заданиями и правилами. Не используйте наказания или команды, на которые партнёр не дал согласия.' },
  { text: 'Лёгкая фиксация рук партнёра', desc: 'Мягко удерживайте руки партнёра во время ласк только после явного согласия. Не выкручивайте суставы, не ограничивайте дыхание и немедленно отпустите руки по просьбе.' },
  { text: 'Обсуждение фантазий вслух перед сном', desc: 'В спокойной обстановке расскажите друг другу о фантазиях, которые готовы только обсуждать или когда-нибудь попробовать. Не требуйте воплощения и не высмеивайте признания партнёра.' },
  { text: 'Секретное свидание с сюрпризом', desc: 'Один партнёр заранее планирует вечер, оставляя часть деталей в тайне, но сообщает всё необходимое для безопасности, одежды и времени. Сюрприз не должен лишать второго возможности отказаться.' },
  { text: 'Совместная ванна при свечах', desc: 'Подготовьте тёплую воду, безопасное освещение и чистые полотенца, а рядом уберите скользкие предметы. Ванна может быть временем для разговоров, объятий и ласк без обязательного продолжения.' },
  { text: 'Спонтанный секс без планирования', desc: 'Позвольте близости начаться неожиданно, но убедитесь, что оба действительно готовы и находитесь в приватном безопасном месте. Спонтанность не отменяет согласие и возможность остановиться.' },
  { text: 'Ролевые костюмы', desc: 'Выберите костюмы или аксессуары, которые помогают почувствовать себя другими персонажами. Заранее обсудите сюжет, границы и удобство одежды, чтобы образ оставался игрой, а не требованием.' },
  { text: 'Вечер долгих объятий и ласк без секса', desc: 'Договоритесь провести вечер в объятиях, поцелуях и нежных прикосновениях без обязательного секса или оргазма. Каждый может остановиться, изменить формат или просто отдыхать рядом.' },
  { text: 'Обмен записками с желаниями', desc: 'Напишите друг другу короткие записки с желаниями, комплиментами или фантазиями и прочитайте их в спокойной обстановке. Обсуждение записки не означает автоматического согласия на её воплощение.' },
  { text: 'Свидание в отеле на одну ночь', desc: 'Выберите легальный и приватный гостиничный номер, заранее уточните правила, бюджет и время заезда. Используйте смену обстановки для отдыха, разговоров и близости без обязательной программы.' },
  { text: 'Секс на балконе', desc: 'Используйте только собственный закрытый балкон, где вас нельзя увидеть или услышать с улицы и из соседних домов. Проверьте устойчивость пола, не приближайтесь к краю и при сомнениях перенесите близость в комнату.' },
  { text: 'Секс в лифте', desc: 'Не практикуйте интимную близость в общественном лифте: это может нарушать правила, затронуть посторонних и создать риск для безопасности. Для похожей ролевой атмосферы разыграйте встречу в лифте дома или в приватном помещении без движения кабины.' },
  { text: 'Секс в бассейне или джакузи', desc: 'Интимная близость в частном бассейне или джакузи, если это разрешено правилами места и обоим удобно сохранять устойчивость на мокрой поверхности.' },
  { text: 'Ролевая игра «массажист и клиент»', desc: 'Один партнёр играет массажиста, а второй — клиента на приватном сеансе, который начинается с обычного массажа и может перейти к близости по взаимному желанию.' },
  { text: 'Ролевая игра «фотограф и модель»', desc: 'Партнёры устраивают домашнюю фотосессию с выбранными образами, позами и лёгким флиртом, заранее договорившись о конфиденциальности снимков.' },
  { text: 'Ролевая игра «доктор и пациент»', desc: 'Совершеннолетние партнёры разыгрывают шуточный медицинский приём с заботой, диалогом и заранее согласованными границами.' },
  { text: 'Ролевая игра «начальник и секретарь»', desc: 'Партнёры играют офисный сценарий с начальником и секретарём, заранее обсудив роли, допустимые команды и стоп-слово.' },
  { text: 'Лёгкие шлепки в процессе близости', desc: 'Лёгкие шлепки по ягодицам можно добавить только после согласия, заранее определив допустимую силу и сигнал для остановки.' },
  { text: 'Дразнящий стриптиз под песню, которую выбрал партнёр', desc: 'Партнёр выбирает песню, а второй исполняет медленный приватный танец с постепенным раздеванием в комфортном для себя темпе.' },
  { text: 'Секс под дождём', desc: 'Близость под тёплым дождём возможна только в полностью приватном и безопасном месте, где нет риска переохлаждения, падения или присутствия посторонних.' },
  { text: 'Секс на рассвете', desc: 'Партнёры встречают рассвет в закрытом приватном месте и переходят к близости после пробуждения и взаимного согласия.' },
  { text: 'Обмен интимными фото друг для друга', desc: 'Партнёры делают и отправляют личные фотографии только при явном согласии, заранее договорившись о хранении, удалении и запрете передачи третьим лицам.' },
  { text: 'Разговор по телефону на интимные темы, пока в разлуке', desc: 'Партнёры обсуждают желания и воспоминания по телефону, заранее убедившись, что каждому комфортен такой формат и разговор не записывается без согласия.' },
  { text: 'Признание вслух в самой смелой фантазии', desc: 'Каждый по очереди рассказывает о фантазии, которую готов только обсуждать или, возможно, когда-нибудь попробовать, без обязанности воплощать её.' },
  { text: 'Общий список фантазий в заметках на телефоне', desc: 'Партнёры создают общий список идей и отмечают, что интересно сейчас, что можно обсудить позже, а что точно не подходит.' },
  { text: 'Массаж с маслом перед сном без продолжения', desc: 'Партнёры по очереди делают массаж с подходящим средством, заранее договорившись, что он не обязан переходить в секс или другие интимные действия.' },
  { text: 'Совместный поход в спа или на массаж', desc: 'Партнёры проводят время в спа или на профессиональном массаже, заранее уточнив правила заведения и оставив интимные действия только для приватного пространства.' },
  { text: 'Ужин при свечах с последующей близостью', desc: 'Партнёры устраивают спокойный ужин при безопасном освещении, а после переходят к нежности или близости только при желании обоих.' },
  { text: 'Медленный танец вдвоём перед сексом', desc: 'Партнёры медленно танцуют лицом друг к другу, сохраняя комфортную дистанцию и позволяя танцу перейти в близость только при взаимном желании.' },
  { text: 'Любовные письма с признаниями друг другу', desc: 'Партнёры пишут друг другу личные письма о чувствах, благодарности и желаниях, а затем читают их вслух или оставляют для повторного чтения.' },
  { text: 'Секс в палатке в походе', desc: 'Близость в палатке возможна только на разрешённой частной территории, при подходящей погоде, устойчивой палатке и полной уверенности в приватности.' },
  { text: 'Уикенд в отеле с джакузи в номере', desc: 'Партнёры выбирают номер с джакузи и проводят выходные вдвоём, соблюдая правила отеля и используя воду только в безопасных положениях.' },
  { text: 'Совместное купание при свечах без спешки', desc: 'Партнёры принимают ванну при безопасном декоративном освещении, проверяют температуру воды и не торопятся переходить к близости.' },
  { text: 'Утренние объятия без спешки перед работой', desc: 'Партнёры оставляют несколько минут на объятия и разговор после пробуждения, не превращая нежность в обязательную прелюдию.' },
  { text: 'Музыка в наушниках на двоих во время близости', desc: 'Партнёры слушают одну музыку через безопасные беспроводные наушники, оставляя возможность слышать речь и стоп-сигнал друг друга.' },
  { text: 'Лёгкая щекотка перьями в процессе ласк', desc: 'Партнёр проводит мягким пером по согласованным участкам кожи, избегая щекотки, если она вызывает раздражение или дискомфорт.' },
  { text: 'Вибратор для двоих во время секса', desc: 'Партнёры используют игрушку для двоих по инструкции, заранее обсудив режим, положение, гигиену и возможность сразу остановиться.' },
  { text: 'Ароматическая свеча для взаимного массажа', desc: 'Партнёры используют только специальную массажную свечу, проверяют температуру воска на руке и не наносят его на слизистые или повреждённую кожу.' },
  { text: 'Съедобный крем или шоколад в ласках', desc: 'Партнёры используют продукт, предназначенный для контакта с кожей и употребления, нанося его только на безопасные участки и проверяя состав заранее.' },
  { text: 'Ролевая игра «случайная встреча в баре»', desc: 'Партнёры разыгрывают знакомство в баре с новыми образами, именами и диалогом, будто видят друг друга впервые.' },
  { text: 'Ролевая игра «звёзды на одну ночь»', desc: 'Один партнёр играет знаменитость, а второй — поклонника, которому удалось получить приватную встречу и внимание звезды.' },
  { text: 'Разговор о новых желаниях за ужином вдвоём', desc: 'Партнёры спокойно обсуждают за ужином желания и фантазии, разделяя идеи для разговора, возможной пробы и обязательного отказа.' },
  { text: 'Флирт по переписке весь день перед встречей', desc: 'Партнёры обмениваются флиртующими сообщениями в течение дня, заранее договорившись о комфортном уровне откровенности и конфиденциальности.' },
  { text: 'Секс под любимую музыку, включённую заранее', desc: 'Партнёры заранее включают выбранный плейлист и используют музыку как фон, не связывая её с обязательным темпом или продолжительностью близости.' },
  { text: 'Совместный закат с последующей близостью', desc: 'Партнёры смотрят закат в разрешённом и безопасном месте, а затем продолжают вечер в полностью приватном пространстве.' },
  { text: 'Секс сразу после пробуждения без разговоров', desc: 'Партнёры заранее обсуждают такой вариант пробуждения, а утром начинают близость только после того, как оба проснулись и готовы продолжать.' },
  { text: 'Медленный эротический стриптиз с элементами танца', desc: 'Партнёр исполняет приватный танец с постепенным снятием одежды, самостоятельно выбирая движения, темп и момент остановки.' },
  { text: 'Ласки по очереди с закрытыми глазами', desc: 'Партнёры по очереди закрывают глаза и получают согласованные ласки, заранее выбрав стоп-сигнал и возможность немедленно прекратить игру.' },
  { text: 'Секс в гостевой комнате для смены обстановки', desc: 'Партнёры используют гостевую комнату только в полностью приватном доме, предварительно проверив устойчивость мебели и свободное пространство.' },
  { text: 'Романтическая фотосессия вдвоём', desc: 'Партнёры делают нежные или немного откровенные фотографии только при взаимном согласии, заранее договорившись о хранении и удалении файлов.' },
  { text: 'Свидание в новом городе на выходные', desc: 'Партнёры выбирают новый город, планируют безопасное место проживания и оставляют время для прогулок, разговоров и близости без обязательного сценария.' },
  { text: 'Секс в уединённом месте на природе', desc: 'Близость возможна только на разрешённой частной территории, где партнёров никто не увидит, не потревожит и не подвергнет опасности.' },
  { text: 'Ролевая игра «случайные соседи»', desc: 'Партнёры разыгрывают знакомство между соседями, придумывают бытовой повод для встречи и постепенно переходят к взаимному флирту.' },
  { text: 'Дразнящие сообщения с намёками в течение недели', desc: 'Партнёры обмениваются лёгкими намёками и обещаниями в течение недели, заранее уважая право любого из них остановить переписку.' },
  { text: 'Секс под плейлист, который собрал партнёр', desc: 'Один партнёр заранее собирает плейлист для вечера, а второй слушает его и делится впечатлениями без обязательства поддерживать определённый темп.' },
  { text: 'Совместная ванна с массажем стоп', desc: 'Партнёры принимают ванну при безопасной температуре воды и по очереди массируют стопы, используя нескользящий коврик и устойчивую опору.' },
  { text: 'Выбор нового белья друг для друга', desc: 'Партнёры вместе выбирают бельё подходящего размера, а каждый решает сам, хочет ли примерять или показывать выбранный комплект.' },
  { text: 'Секс в машине на смотровой площадке', desc: 'Интимная близость в припаркованной машине допустима только на разрешённой частной территории, где нет риска быть замеченными или помешать другим людям.' },
  { text: 'Ролевая игра «собеседование на работу»', desc: 'Партнёры разыгрывают шуточное собеседование на вымышленную должность, заранее договорившись о границах офисного флирта и возможном завершении игры.' },
  { text: 'Признание в любимой части тела партнёра', desc: 'Каждый партнёр подробно рассказывает, какая часть тела другого ему нравится и почему, избегая сравнений и оценок, которые могут задеть.', },
  { text: 'Секс с лёгким доминированием партнёрши', desc: 'Партнёрша выбирает темп и последовательность действий в заранее согласованных границах, используя стоп-слово и право партнёра остановить игру.' },
  { text: 'Утренний кофе в постели и неспешная близость', desc: 'Партнёр приносит кофе или другой напиток в постель, а затем пара проводит утро без спешки, переходя к близости только при взаимном желании.' },
  { text: 'Секс у окна с задёрнутыми шторами', desc: 'Близость у окна в полностью приватной комнате с задёрнутыми шторами и мягким приглушённым светом.' },
  { text: 'Общий дневник интимных желаний', desc: 'Партнёры по очереди записывают в одну тетрадь свои мечты, границы и желания, которые хотят обсудить вместе.' },
  { text: 'Долгий поцелуйный марафон без продолжения', desc: 'Партнёры долго и медленно целуются без обязательного перехода к сексу, сосредотачиваясь только на ощущениях и близости.' },
  { text: 'Записка-приглашение на романтический вечер', desc: 'Один партнёр оставляет рукописную записку с приглашением на заранее подготовленный вечер для двоих.' },
  { text: 'Ролевая игра «репетитор и ученица»', desc: 'Совершеннолетние партнёры разыгрывают домашнее занятие с репетитором, заранее согласовав роли, флирт и границы сценария.' },
  { text: 'Секс с чередованием ролей ведущего и ведомого', desc: 'Партнёры по очереди задают темп и предлагают действия, сохраняя возможность остановиться или изменить сценарий в любой момент.' },
  { text: 'Спа-вечер вдвоём с ароматными маслами', desc: 'Партнёры устраивают домашний спа-вечер с мягким светом, подходящими маслами и массажем без обязательного продолжения.' },
  { text: 'Секс во время грозы или шторма за окном', desc: 'Партнёры остаются в закрытом безопасном помещении и проводят близость под звуки грозы, не выходя на улицу во время непогоды.' },
  { text: 'Секс в сауне', desc: 'Близость в частной сауне возможна только при подходящей температуре, достаточном охлаждении и соблюдении правил места; при перегреве нужно сразу остановиться.' },
  { text: 'Секс на крыше дома', desc: 'Такой вариант допустим только на частной оборудованной террасе или другой разрешённой площадке с ограждением, устойчивым покрытием и полной приватностью.' },
  { text: 'Секс в лесу у костра', desc: 'Близость возможна только на разрешённой территории, вдали от посторонних, при полностью контролируемом костре и соблюдении правил пожарной безопасности.' },
  { text: 'Секс на пляже ночью', desc: 'Интимная близость возможна только на разрешённом частном пляже или закрытой территории, где нет риска быть замеченными или потревоженными.' },
  { text: 'Секс в примерочной магазина', desc: 'Интимная близость в примерочной магазина недопустима из-за отсутствия приватности и возможного нарушения правил. Безопасная замена — ролевая игра «примерочная» дома.' },
  { text: 'Секс в домашнем кабинете', desc: 'Партнёры переносят близость в закрытый домашний кабинет, предварительно убирая острые, хрупкие и мешающие предметы.' },
  { text: 'Секс в прачечной комнате', desc: 'Партнёры используют только безопасное домашнее помещение после остановки техники, освобождения прохода и проверки устойчивости поверхностей.' },
  { text: 'Секс на лестничной клетке', desc: 'Интимная близость в общем подъезде небезопасна и может нарушать приватность и правила общественного места. Безопасная замена — домашняя ролевая сцена «между этажами».' },
  { text: 'Секс в гардеробной', desc: 'Партнёры используют закрытую домашнюю гардеробную только при наличии свободного пространства, устойчивого пола и возможности свободно двигаться.' },
  { text: 'Ролевая игра «горничная и хозяин дома»', desc: 'Партнёры разыгрывают бытовую сцену с уборкой, которая по взаимному желанию переходит во флирт и близость.' },
  { text: 'Ролевая игра «полицейский и нарушитель»', desc: 'Партнёры разыгрывают шуточный допрос с заранее согласованными ролями, границами и стоп-словом; фиксация допустима только при взаимном согласии.' },
  { text: 'Ролевая игра «репортёр и звезда»', desc: 'Один партнёр играет репортёра, другой — звезду, а интервью постепенно становится личным разговором и флиртом по взаимному желанию.' },
  { text: 'Ролевая игра «бывшие одноклассники»', desc: 'Совершеннолетние партнёры разыгрывают случайную встречу спустя годы, вспоминают прошлое и заново знакомятся в вымышленном сценарии.' },
  { text: 'Ролевая игра «частный детектив»', desc: 'Партнёр расследует вымышленную тайну с помощью подсказок, вопросов и ролевого флирта, заранее согласовав допустимые элементы игры.' },
  { text: 'Ролевая игра «королева и слуга»', desc: 'Один партнёр ведёт сценарий и отдаёт заранее согласованные команды, а второй добровольно следует им с возможностью немедленно остановить игру.' },
  { text: 'Ролевая игра «капитан и матрос»', desc: 'Партнёры разыгрывают морской сценарий с дисциплиной, командами и заботой, заранее определив границы и стоп-сигнал.' },
  { text: 'Ролевая игра «психолог и клиент»', desc: 'Совершеннолетние партнёры разыгрывают доверительный разговор в вымышленной роли, не заменяя настоящую психологическую помощь и заранее согласовав границы.' },
  { text: 'Ролевая игра «танцовщица на заказ»', desc: 'Партнёрша исполняет приватный танец только для партнёра, самостоятельно выбирая образ, движения, темп и момент завершения.' },
  { text: 'Ролевая игра «тайное свидание в отеле»', desc: 'Партнёры разыгрывают встречу двух людей, которые будто бы тайно увиделись в гостиничном номере, сохраняя сценарий в полностью приватной обстановке.' },
  { text: 'Ролевая игра «первое свидание» с нуля', desc: 'Партнёры знакомятся заново, придумывают новые детали образов и проходят путь от первого разговора до близости только при взаимном желании.' },
  { text: 'Ролевая игра «воссоединение старых влюблённых»', desc: 'Партнёры разыгрывают встречу после долгой разлуки, вспоминают прошлые чувства и постепенно возвращают романтическую связь.' },
  { text: 'Ролевая игра «тайный поклонник»', desc: 'Один партнёр оставляет анонимные записки или небольшие знаки внимания, а вечером раскрывает свою личность и продолжает романтический сценарий.' },
  { text: 'Ролевая игра «встреча спустя годы»', desc: 'Партнёры играют двух людей, которые давно не виделись, и заново знакомятся в вымышленной встрече без сравнения с реальными отношениями.' },
  { text: 'Секс с шёлковой лентой вместо верёвки', desc: 'Шёлковую ленту можно использовать только для символической мягкой фиксации, не затягивая её и оставляя быстрый способ освободиться.' },
  { text: 'Массажный вибратор для расслабления перед близостью', desc: 'Партнёры используют массажный вибратор на безопасных участках тела и постепенно переходят к близости только при желании обоих.' },
  { text: 'Перо и кубик льда одновременно в одних ласках', desc: 'Партнёры чередуют лёгкие прикосновения пером и краткий контакт с холодом, избегая длительного охлаждения кожи и участков с нарушенной чувствительностью.' },
  { text: 'Ароматизированный лубрикант с новым вкусом', desc: 'Партнёры используют лубрикант, подходящий для оральных ласк, предварительно проверив состав, срок годности и реакцию кожи.' },
  { text: 'Съедобное бельё', desc: 'Партнёры используют съедобное бельё только как игровую деталь, проверив состав и отсутствие аллергии, а снятие выполняют только по взаимному желанию.' },
  { text: 'Разогревающее массажное масло', desc: 'Партнёры используют специальное массажное средство с разогревающим эффектом, сначала проверив небольшое количество на коже и избегая слизистых.' },
  { text: 'Свеча для капель тёплого воска на коже', desc: 'Используйте только специальную массажную свечу, проверяйте температуру воска на руке и наносите его на небольшие участки неповреждённой кожи.' },
  { text: 'Мягкие наручники из бархата или меха', desc: 'Мягкие наручники используют ненадолго, не затягивают и оставляют рядом средство быстрого освобождения; при онемении или боли игру сразу прекращают.' },
  { text: 'Лёгкий флоггер для игривых прикосновений', desc: 'Мягкий флоггер используют только по согласованным зонам и с заранее определённой силой, избегая головы, шеи, позвоночника и области почек.' },
  { text: 'Шёлковый платок вместо обычной повязки на глаза', desc: 'Шёлковый платок используют как мягкую повязку, оставляя возможность слышать речь партнёра и немедленно снять его по просьбе.' },
  { text: 'Утренний секс в выходной без будильника', desc: 'Партнёры проводят утро без спешки и переходят к близости после пробуждения только при ясном желании обоих.' },
  { text: 'Близость в перерыве посреди рабочего дня', desc: 'Партнёры выделяют короткое приватное время в течение дня, заранее убедившись, что им не нужно спешить, а близость не нарушит рабочие обязанности.' },
  { text: 'Вечерний секс как ежедневный ритуал перед сном', desc: 'Партнёры могут сделать близость вечерним ритуалом, но сохраняют право на объятия, разговор или отдых без обязательного секса.' },
  { text: 'Ночной секс, когда весь дом уже спит', desc: 'Близость глубокой ночью возможна только при полной приватности, когда оба партнёра проснулись, согласны и не нарушают сон или личные границы других людей.' },
  { text: 'Секс во время снегопада за окном', desc: 'Партнёры остаются в тёплом закрытом помещении и проводят близость под видом снегопада, поддерживая комфортную температуру в комнате.' },
  { text: 'Секс жарким летним вечером у открытого окна', desc: 'Партнёры используют открытое окно только при полной приватности, отсутствии риска быть услышанными или увиденными и комфортной температуре.' },
  { text: 'Секс в холодный зимний вечер под одним пледом', desc: 'Партнёры устраивают близость в тёплом помещении, используя плед для комфорта и не продолжая, если кому-то холодно или неудобно.' },
  { text: 'Секс с открытым окном и звуками ночного города', desc: 'Партнёры выбирают приватную комнату, проверяют, что их не видно и не слышно снаружи, и используют звуки города только как фон.' },
  { text: 'Особенный вечер близости в годовщину отношений', desc: 'Отметьте годовщину романтическим ужином, разговором о совместных воспоминаниях и нежным вечером без обязательного сценария.' },
  { text: 'День рождения партнёра, который начинается с ласк', desc: 'Начните день рождения с заранее согласованных нежных прикосновений, поцелуев и времени вдвоём вместо обычного будильника.' },
  { text: 'Нежная встреча после долгой разлуки', desc: 'После разлуки начните с объятий, разговора и спокойного восстановления контакта, переходя к близости только при взаимном желании.' },
  { text: 'Вечер примирения после ссоры', desc: 'Сначала спокойно обсудите конфликт и восстановите чувство безопасности, а затем решите, хочется ли вам объятий или близости.' },
  { text: 'Объятия и близость сразу после встречи в аэропорту', desc: 'В аэропорту ограничьтесь приветственными объятиями и поцелуем, а интимную близость оставьте для приватного места после возвращения домой.' },
  { text: 'Медовый месяц дома, без единого выхода на улицу', desc: 'Проведите выходные дома без обязательных дел, приготовьте еду, отключите уведомления и оставьте время для отдыха и близости.' },
  { text: 'Купон на желание, который можно вручить в любой момент', desc: 'Создайте бумажный купон на просьбу или совместное желание, заранее указав, что партнёр может отказаться или предложить альтернативу.' },
  { text: 'Общая тетрадь открытых фантазий, которую заполняете вместе', desc: 'По очереди записывайте фантазии, границы и идеи для обсуждения, разделяя то, что хочется воплотить, обсудить или оставить только в воображении.' },
  { text: 'Список того, что оба хотите попробовать до конца года', desc: 'Составьте общий список желаний и отметьте пункты, которые интересны обоим, а также условия, при которых их можно будет попробовать.' },
  { text: 'Общий плейлист музыки, которая возбуждает вас обоих', desc: 'Соберите плейлист из песен, которые создают подходящее настроение, и используйте его как фон без обязательства подстраиваться под ритм музыки.' },
  { text: 'Вечер комплиментов только о теле и характере партнёра', desc: 'По очереди говорите искренние комплименты внешности, характеру и поступкам партнёра, избегая сравнений и оценок, которые могут задеть.' },
  { text: 'Признание в самом ярком моменте близости за всё время', desc: 'Расскажите, какой момент близости запомнился сильнее всего, и объясните, какие чувства или детали сделали его особенным.' },
  { text: 'Разговор о том, что каждому нравится больше всего в постели', desc: 'Спокойно обсудите любимые прикосновения, темп, позы и границы, не превращая разговор в критику или требование изменить всё сразу.' },
  { text: 'Романтический фильм с продолжением после титров', desc: 'Посмотрите фильм, а после титров обсудите впечатления и решите, хочется ли продолжить вечер поцелуями, объятиями или близостью.' },
  { text: 'Чувственное аудио перед сном вместо обычного плейлиста', desc: 'Включите чувственную аудиозапись только при взаимном желании и заранее договоритесь, что любой из партнёров может её выключить.' },
  { text: 'Секс с завязанными глазами и музыкой в наушниках одновременно', desc: 'Не лишайте партнёра одновременно зрения и слуха: используйте мягкую повязку, но оставьте возможность слышать речь и стоп-сигнал.' },
  { text: 'Долгий поцелуй у двери перед тем как начать раздеваться', desc: 'Остановитесь у двери и несколько минут целуйтесь, не торопясь переходить к раздеванию или дальнейшей близости.' },
  { text: 'Медленное раздевание партнёра руками, без спешки', desc: 'Медленно снимайте одежду друг с друга, заранее договорившись, какие предметы одежды и действия комфортны каждому.' },
  { text: 'Раздевание партнёра на ощупь в полной темноте', desc: 'Оставьте мягкое безопасное освещение рядом и медленно помогайте друг другу раздеваться на ощупь, сохраняя возможность видеть и слышать партнёра.' },
  { text: 'Массажный ролик для тела перед близостью', desc: 'Используйте массажный ролик на спине, плечах и ногах с умеренным давлением, избегая позвоночника, суставов и болезненных участков.' },
  { text: 'Тёплое полотенце после душа как часть ласк', desc: 'После душа заверните партнёра в тёплое полотенце и помогите вытереться, переходя к нежным прикосновениям только при взаимном желании.' },
  { text: 'Ванна с пеной и свечами одновременно', desc: 'Подготовьте ванну с комфортной температурой воды и безопасным декоративным светом, убрав всё, о что можно поскользнуться.' },
  { text: 'Контрастный душ вдвоём по утрам', desc: 'Чередуйте тёплую и прохладную воду без резких перепадов, избегая контрастного душа при плохом самочувствии или противопоказаниях.' },
  { text: 'Секс на подушках на полу вместо кровати', desc: 'Используйте чистый матрас или устойчивую мягкую поверхность на полу, убрав предметы, о которые можно споткнуться.' },
  { text: 'Секс на балконе отеля с видом на море', desc: 'Интимная близость на балконе допустима только при полной приватности и отсутствии риска быть увиденными; безопаснее выбрать закрытый номер.' },
  { text: 'Секс в палатке в горах вдали от людей', desc: 'Выберите разрешённое безопасное место, проверьте погоду, устойчивость палатки, связь и возможность быстро покинуть территорию.' },
  { text: 'Секс у камина зимним вечером', desc: 'Оставьте безопасное расстояние от огня, уберите горючие ткани и используйте устойчивую поверхность, чтобы не перегреться и не получить ожог.' },
  { text: 'Секс на чердаке загородного дома', desc: 'Используйте только сухой, проветриваемый и устойчивый чердак с достаточным пространством, освещением и безопасным выходом.' },
  { text: 'Лёгкий шёпот на ухо во время близости', desc: 'Шёпотом говорите о чувствах, желаниях и ощущениях, заранее избегая слов и тем, которые могут быть неприятны партнёру.' },
  { text: 'Дразнящие фото-намёки в переписке, не раскрывающие всего', desc: 'Отправляйте только такие фотографии, на которые оба согласны, без лица или других идентифицирующих деталей, и заранее договоритесь о конфиденциальности.' },
  { text: 'Совместный выбор фильма для взрослых на вечер', desc: 'Выберите контент вместе, обсудите ожидания и помните, что просмотр не означает обязательства повторять увиденное.' },
  { text: 'Танец на коленях в качестве подарка партнёру', desc: 'Партнёр исполняет приватный танец на коленях, самостоятельно выбирая движения, одежду, продолжительность и момент остановки.' },
  { text: 'Медленный массаж головы и шеи перед близостью', desc: 'Мягко массируйте голову, плечи и шею, избегая сильного давления и передней части шеи, где нельзя сдавливать дыхательные пути.' },
  { text: 'Горячий напиток и плед перед тем, как перейти к близости', desc: 'Согрейтесь напитком и пледом, проведите время в разговоре и переходите к близости только при взаимном желании.' },
  { text: 'Романтический пикник с продолжением дома', desc: 'Проведите пикник в разрешённом месте, а после возвращения домой продолжите вечер разговором, объятиями или близостью.' },
  { text: 'Утренняя прогулка, которая заканчивается близостью дома', desc: 'Прогуляйтесь утром, а после возвращения домой отдохните и решите, хочется ли продолжить день нежностью или близостью.' },
  { text: 'Вечер настольной игры, который перерастает в нежность', desc: 'Добавьте к настольной игре добровольные романтические задания, заранее исключив действия, которые одному из партнёров не подходят.' },
  { text: 'Секс сразу после совместной тренировки', desc: 'После тренировки сначала восстановите дыхание, выпейте воды и примите душ, а затем переходите к близости только при хорошем самочувствии обоих.' },
  { text: 'Совместная йога с моментом близости после практики', desc: 'Выполните спокойную совместную растяжку и дыхательные упражнения, а после практики переходите к близости только при взаимном желании.' },
  { text: 'Обещание исполнить желание партнёра, данное заранее', desc: 'Пообещайте обсудить и выполнить одно желание партнёра, но оставьте право изменить решение, предложить альтернативу или остановиться в любой момент.' },
  { text: 'Тайный знак в течение дня, обозначающий желание вечером', desc: 'Придумайте нейтральный знак или слово, которое означает желание провести вечер вдвоём, но не является автоматическим согласием на секс.' },
  { text: 'Живая музыка, которую один играет для другого перед близостью', desc: 'Один партнёр исполняет музыку для другого, а затем вы решаете, хочется ли продолжить вечер разговором, объятиями или близостью.' },
  { text: 'Чтение стихов друг другу перед тем, как перейти к ласкам', desc: 'Прочитайте друг другу выбранные стихи, обсудите впечатления и переходите к ласкам только при взаимном желании.' },
  { text: 'Бокал шампанского в постели', desc: 'Выпейте напиток в постели, используя устойчивые бокалы и помня, что алкоголь не должен влиять на способность дать ясное согласие.' },
  { text: 'Клубника с шампанским перед вечером вдвоём', desc: 'Подготовьте клубнику и напиток как часть романтического вечера, учитывая аллергии и не связывая угощение с обязательством продолжать близость.' },
  { text: 'Совместный плотный завтрак после утренней близости', desc: 'После утренней близости приготовьте сытный завтрак вместе или заранее, уделив время восстановлению, воде и спокойному общению.' },
  { text: 'Утренний секс с последующим общим душем', desc: 'После пробуждения переходите к близости только при ясном желании обоих, а затем примите душ вместе, соблюдая осторожность на скользком полу.' },
  { text: 'Секс при свете камина и приглушённом освещении', desc: 'Используйте камин только при соблюдении пожарной безопасности и добавьте безопасный источник света, чтобы свободно видеть окружающее пространство.' },
  { text: 'Секс на диване вместо кровати для разнообразия', desc: 'Перенесите близость на устойчивый диван, предварительно освободив его от предметов и проверив, что обоим удобно сохранять положение.' },
  { text: 'Близость в гостиной, пока дома больше никого нет', desc: 'Проводите близость в гостиной только при полной приватности и отсутствии риска, что кто-то неожиданно войдёт или увидит происходящее.' },
  { text: 'Вечер без телефонов, полностью посвящённый друг другу', desc: 'Уберите телефоны в другую комнату, заранее оставив способ связаться в экстренной ситуации, и проведите вечер за разговором, отдыхом и близостью без отвлечений.' },
  { text: 'Домашнее «свидание» перед тем, как перейти к близости', desc: 'Устройте дома полноценное свидание с ужином, красивой обстановкой и разговором, а затем решите, хочется ли продолжить вечер близостью.' },
  { text: 'Признание в тайной симпатии, будто вы только познакомились', desc: 'Разыграйте первое знакомство и признайтесь друг другу в симпатии так, будто встретились всего несколько часов назад.' },
  { text: 'Обещание рассказать о своих желаниях после близости', desc: 'Заранее договоритесь после близости спокойно поделиться желаниями и впечатлениями, без обязательства воплощать всё сказанное.' },
  { text: 'Массаж плеч после тяжёлого дня, переходящий в ласки', desc: 'Начните с расслабляющего массажа плеч, а затем переходите к ласкам только при взаимном желании и отсутствии дискомфорта.' },
  { text: 'Романтический завтрак в постель как сюрприз', desc: 'Подготовьте завтрак и принесите его партнёру в постель, начав день с заботы, разговора и времени вдвоём.' },
  { text: 'Вечер, полностью посвящённый удовольствию только партнёра', desc: 'Заранее договоритесь сосредоточиться на удовольствии партнёра, но сохраняйте право остановиться и не превращайте заботу в обязанность.' },
  { text: 'Секс в юбке или платье, не снимая его до конца', desc: 'Партнёрша оставляет платье или юбку на себе во время близости, если одежда не мешает движениям и обоим комфортно.' },
  { text: 'Медленный обмен любимыми воспоминаниями перед сном, ведущий к близости', desc: 'Перед сном расскажите друг другу о тёплых общих воспоминаниях и переходите к близости только при взаимном желании.' },
  { text: 'Анальные ласки', desc: 'Начните с внешних прикосновений и двигайтесь постепенно, используя лубрикант, чистые руки и заранее согласованный сигнал остановки.' },
  { text: 'Анальный секс', desc: 'Практика требует полного согласия, медленного темпа, достаточного лубриканта, презерватива и остановки при боли или дискомфорте.' },
  { text: 'Массаж простаты', desc: 'Используйте только чистые руки или специальную игрушку с широким ограничителем, большое количество лубриканта и медленный темп.' },
  { text: 'Анальная пробка для новых ощущений', desc: 'Выберите небольшую игрушку с широким основанием, используйте лубрикант и прекращайте при боли, онемении или неприятных ощущениях.' },
  { text: 'Шлепки по ягодицам рукой', desc: 'Добавьте лёгкие шлепки только после согласия, заранее определив силу, допустимые зоны и стоп-сигнал.' },
  { text: 'Шлепки плёткой', desc: 'Используйте мягкую плётку для лёгких ударов по согласованным зонам, избегая позвоночника, шеи, головы и области почек.' },
  { text: 'Шлепки шлёпалкой', desc: 'Применяйте шлёпалку только после обсуждения силы и границ, начиная с лёгких ударов по ягодицам и регулярно проверяя реакцию партнёра.' },
  { text: 'Продолжительные оральные ласки до финала', desc: 'Партнёр продолжает оральные ласки до оргазма только при взаимном желании, сохраняя комфортный темп и возможность сделать паузу.' },
  { text: 'Одновременные оральные ласки друг другу', desc: 'Партнёры одновременно ласкают друг друга в устойчивом и удобном положении, заранее договорившись о темпе и возможности остановиться.' },
  { text: 'Ролевая игра «строгая госпожа»', desc: 'Партнёрша ведёт заранее согласованный сценарий, отдаёт команды и контролирует темп, а стоп-слово немедленно прекращает игру.' },
  { text: 'Ролевая игра «покорный партнёр»', desc: 'Один партнёр добровольно следует заранее согласованным указаниям другого, сохраняя право отказаться от любого отдельного действия.' },
  { text: 'Более выраженная игра в доминирование и подчинение', desc: 'Заранее обсудите роли, границы, стоп-слово и действия, которые разрешены; интенсивность игры увеличивайте постепенно.' },
  { text: 'Стоп-слово для более смелых игр', desc: 'Выберите короткое слово или сигнал, который означает немедленную остановку без вопросов и споров в любой момент.' },
  { text: 'Символический ошейник на один вечер', desc: 'Используйте ошейник только как декоративный символ роли, не затягивая его и не ограничивая дыхание или движения.' },
  { text: 'Полная фиксация тела мягкими лентами', desc: 'Полная фиксация несёт риски; безопаснее ограничить игру мягкой фиксацией одной зоны, оставить быстрый способ освобождения и постоянно контролировать самочувствие.' },
  { text: 'Ощущение лёгкой беспомощности под контролем партнёра', desc: 'Партнёр добровольно передаёт часть контроля в заранее оговорённых границах, сохраняя возможность остановить процесс в любой момент.' },
  { text: 'Вагинальные шарики в течение дня', desc: 'Используйте только подходящую игрушку по инструкции, ограничьте продолжительность и прекратите ношение при боли, кровотечении или дискомфорте.' },
  { text: 'Более мощная игрушка для интенсивных ощущений', desc: 'Начните с низкой мощности, заранее договоритесь о границах и прекратите использование при боли, онемении или неприятных ощущениях.' },
  { text: 'Ролевая игра «строгий тренер»', desc: 'Партнёр играет требовательного тренера в вымышленном сценарии, используя только заранее согласованные команды и безопасные игровые задания.' },
  { text: 'Смелые слова во время близости', desc: 'Обсудите заранее, какие выражения допустимы, и используйте только те слова, которые не задевают и не вызывают дискомфорт у партнёра.' },
  { text: 'Лёгкие укусы и царапины в процессе ласк', desc: 'Начинайте с мягких укусов и прикосновений ногтями, избегая лица, шеи и повреждения кожи; сразу остановитесь при боли или следах.' },
  { text: 'Игрушка с необычной текстурой', desc: 'Выберите игрушку с новой текстурой, изучите инструкцию и начните с короткого использования на комфортной интенсивности.' },
  { text: 'Ролевая игра «военный в увольнительной»', desc: 'Партнёры разыгрывают встречу с военным после увольнения, используя образ, диалог и флирт без настоящих приказов или давления.' },
  { text: 'Ролевая игра «строгий инструктаж»', desc: 'Один партнёр даёт заранее согласованные подробные указания, а второй может отказаться от любого задания или остановить сценарий.' },
  { text: 'Двойная стимуляция вибратором во время секса', desc: 'Используйте подходящий для пары вибратор во время проникновения, начиная с низкой мощности и меняя положение только при комфорте обоих.' },
  { text: 'Ролевая игра «наказание за опоздание»', desc: 'Разыграйте символическое наказание в виде задания, поцелуев или лёгких шлепков только после предварительного согласия и без реального давления.' },
  { text: 'Лёгкая фиксация ног партнёра', desc: 'Мягко удерживайте ноги только после согласия, не выкручивая суставы и не ограничивая дыхание или кровообращение.' },
  { text: 'Использование эрекционного кольца', desc: 'Используйте кольцо строго по инструкции и ограниченное время; снимите его при боли, онемении, отёке или изменении цвета кожи.' },
  { text: 'Ролевая игра «непослушный сосед»', desc: 'Партнёры разыгрывают встречу соседей с взаимным флиртом, заранее определив роли, допустимые действия и момент завершения сценария.' },
  { text: 'Смена ролей ведущего в доминировании на вечер', desc: 'Обычно ведомый партнёр получает роль ведущего и задаёт темп в пределах заранее согласованных границ и стоп-слова.' },
  { text: 'Игра с несколькими игрушками за один вечер', desc: 'Используйте игрушки по очереди, очищая их между разными зонами и делая паузы, если появляется усталость или дискомфорт.' },
  { text: 'Продолжительная прелюдия с элементами лёгкой доминации', desc: 'Один партнёр уверенно направляет прелюдию через согласованные команды, но регулярно проверяет комфорт второго и принимает просьбу об остановке.' },
  { text: 'Ролевая игра «случайный гость отеля»', desc: 'Партнёры разыгрывают случайную встречу в гостиничном коридоре, но продолжают сценарий только в приватном номере и при взаимном желании.' },
  { text: 'Секс с чередованием интенсивности от нежного до более резкого', desc: 'Постепенно меняйте темп и силу только после согласия, избегая резких движений и возвращаясь к более мягкому формату при любом дискомфорте.' },
  { text: 'Массаж с элементами лёгкого доминирования', desc: 'Один партнёр ведёт массаж и выбирает порядок действий, заранее согласовав допустимую силу, зоны тела и стоп-сигнал.' },
  { text: 'Ролевая игра «допрос»', desc: 'Проведите вымышленный допрос с заранее согласованными вопросами, ролями и стоп-словом, не используя угрозы или реальные личные секреты.' },
  { text: 'Использование мягкой плети для всего тела', desc: 'Используйте плеть только на безопасных участках тела, избегая головы, шеи, позвоночника, суставов и области почек.' },
  { text: 'Ролевая игра «непокорная партнёрша»', desc: 'Партнёрша играет сопротивление только в рамках заранее согласованного сценария, а все действия прекращаются сразу после реальной просьбы остановиться.' },
  { text: 'Секс с более настойчивым темпом по обоюдному согласию', desc: 'Заранее обсудите допустимый темп и сигнал для остановки, начиная постепенно и постоянно ориентируясь на реакцию обоих.' },
  { text: 'Игра в «плен» с мягкими путами', desc: 'Разыграйте символическое пленение с мягкими путами, оставив быстрый способ освобождения и заранее определив действия, которые исключены.' },
  { text: 'Ролевая игра «страстный незнакомец в отпуске»', desc: 'Партнёры разыгрывают знакомство в отпуске с новыми образами и флиртом, продолжая игру только в приватной обстановке.' },
  { text: 'Использование массажной насадки для более интенсивных ощущений', desc: 'Используйте массажную насадку на безопасных участках тела, начиная с минимальной мощности и прекращая при боли, онемении или раздражении.' },
  { text: 'Ролевая игра «хозяйка положения»', desc: 'Партнёрша ведёт вечер и выбирает порядок действий только в пределах заранее согласованных границ, а партнёр может остановить игру в любой момент.' },
  { text: 'Долгая словесная прелюдия с откровенными признаниями о желаниях', desc: 'Партнёры подробно рассказывают о своих желаниях, границах и ожиданиях, не превращая разговор в обязательство что-либо воплощать.' },
  { text: 'Ролевая игра «жёсткие переговоры»', desc: 'Партнёры разыгрывают деловые переговоры за закрытой дверью и заранее определяют, какие элементы флирта допустимы в сценарии.' },
  { text: 'Секс с использованием нескольких точек стимуляции одновременно', desc: 'Партнёры одновременно стимулируют несколько согласованных зон, начиная с мягкого темпа и прекращая при дискомфорте.' },
  { text: 'Ролевая игра «частный урок дисциплины»', desc: 'Один партнёр играет требовательного наставника, а второй выполняет только заранее согласованные задания с правом отказаться от любого пункта.' },
  { text: 'Смена привычных ролей в паре на один вечер', desc: 'Партнёры меняются привычными ролями: тот, кто обычно ведёт, получает возможность следовать, а второй берёт инициативу в оговорённых пределах.' },
  { text: 'Игра с лёгким ограничением движений', desc: 'Используйте мягкую фиксацию или удерживание только после согласия, оставив быстрый способ освобождения и стоп-сигнал.' },
  { text: 'Откровенный разговор о более смелых желаниях за пределами привычного', desc: 'Обсудите желания, которые выходят за рамки привычного, и разделите их на фантазии, идеи для обсуждения и действия, к которым готовы оба.' },
  { text: 'Секс-лотерея с уровнями смелости', desc: 'Подготовьте карточки с заданиями разной интенсивности и заранее договоритесь, что любую карту можно пропустить без объяснений.' },
  { text: 'Три желания партнёра', desc: 'Каждый записывает три желания, а затем вы по очереди выбираете только те, которые подходят обоим, и обсуждаете безопасный способ их выполнить.' },
  { text: 'Эротический чек-лист', desc: 'Разделите идеи на «хочу сейчас», «возможно позже» и «не подходит», а для вечера выберите только совпавшие желания.' },
  { text: 'Секс с паузами на обратную связь', desc: 'После каждого этапа делайте короткую паузу и обсуждайте, что было приятно, что изменить и хочется ли продолжать.' },
  { text: 'Игра «медленнее или смелее»', desc: 'Партнёр в любой момент выбирает, замедлиться или немного усилить интенсивность, а второй подтверждает, что ему комфортно.' },
  { text: 'Случайная поза из книги', desc: 'Откройте книгу или приложение и выберите только ту позу, которая физически удобна, безопасна и подходит обоим.' },
  { text: 'Вечер взаимного обучения', desc: 'Каждый показывает одну любимую технику ласк, а второй спокойно сообщает, что приятно и что хотелось бы изменить.' },
  { text: 'Эротический массаж с выбором давления', desc: 'Партнёр заранее выбирает комфортную силу давления, а массажист постепенно меняет интенсивность, ориентируясь на обратную связь.' },
  { text: 'Игра «одна зона за раз»', desc: 'Выберите одну часть тела и уделите ей несколько минут, переходя дальше только после согласия и положительной реакции партнёра.' },
  { text: 'Смена ведущего каждые пять минут', desc: 'По таймеру партнёры меняются ролями: один задаёт ритм, второй принимает ласки, после чего роли меняются.' },
  { text: 'Ночной квест по квартире', desc: 'Разложите записки с романтическими заданиями по безопасным комнатам, чтобы каждая подсказка вела к следующему этапу вечера.' },
  { text: 'Отель на одну ночь в своём городе', desc: 'Снимите номер в разрешённом отеле и проведите вечер в новой обстановке, соблюдая правила проживания и сохраняя приватность.' },
  { text: 'Свидание с тайным дресс-кодом', desc: 'Заранее выберите друг для друга образ, встретьтесь вечером и раскройте задумку только перед началом свидания.' },
  { text: 'Эротическое меню', desc: 'Составьте меню из поцелуев, массажа, ласк и более смелых желаний, а затем каждый выберет только подходящие обоим пункты.' },
  { text: 'Дегустация вкусов на коже', desc: 'Используйте безопасные съедобные продукты только на внешней коже, заранее проверив состав, аллергию и отсутствие раздражения.' },
  { text: 'Вечер с эротическим аудио', desc: 'Выберите чувственную аудиозапись, приглушите свет и используйте голос как фон, сохраняя возможность остановить запись в любой момент.' },
  { text: 'Игра «угадай желание»', desc: 'Один описывает желание намёками, второй пытается угадать его, после чего вы обсуждаете, хочется ли воплощать идею или оставить её фантазией.' },
  { text: 'Фотограф и модель без публикации', desc: 'Проведите личную фотосессию только при взаимном согласии, заранее договорившись о хранении, удалении и запрете передачи снимков.' },
  { text: 'Секретный образ на вечер', desc: 'Один партнёр выбирает образ и аксессуары для другого, а тот видит результат перед началом свидания и может отказаться от любого элемента.' },
  { text: 'Вечер запретных слов', desc: 'Договоритесь о нескольких словах, которые не используете, и заменяйте их жестами или взглядами, сохраняя возможность прямо сказать «стоп».' },
  { text: 'Поцелуи по маршруту', desc: 'Один партнёр выбирает безопасный маршрут по телу от нейтральных зон к более чувствительным, переходя дальше только при согласии.' },
  { text: 'Эротическая карта тела', desc: 'Отметьте на схеме тела зоны «приятно», «можно попробовать» и «не трогать», а затем исследуйте только совпавшие варианты.' },
  { text: 'Игра с тремя тканями', desc: 'Используйте мягкую, гладкую и фактурную ткань на внешней коже, сравнивая ощущения и прекращая прикосновения, если они неприятны.' },
  { text: 'Тёплое и прохладное дыхание', desc: 'Чередуйте тёплое дыхание и лёгкие прикосновения на согласованных участках тела, ориентируясь на реакцию партнёра.' },
  { text: 'Общий плейлист для близости', desc: 'Каждый выбирает по пять композиций, а затем выстраиваете из них музыкальный сценарий вечера без обязательства следовать ритму песен.' },
  { text: 'Эротический танец с остановками', desc: 'Танцуйте медленно, а при остановке музыки замирайте в удобной позе и сохраняйте зрительный контакт только столько, сколько комфортно обоим.' },
  { text: 'Свидание в домашнем кинотеатре', desc: 'Создайте атмосферу кинотеатра, выберите фильм и договоритесь не пользоваться телефонами, оставив возможность прервать просмотр.' },
  { text: 'Ритуал после близости', desc: 'Заранее выберите спокойный ритуал после интимного времени: вода, объятия, разговор, плед или совместный душ.' },
  { text: 'Игра «что оставить на потом»', desc: 'Каждый выбирает одно желание, которое специально откладывается до следующей встречи, чтобы сохранить предвкушение без давления.' },
  { text: 'Интимный обмен ролями', desc: 'Партнёры по очереди ведут процесс и принимают ласки, заранее определив границы и возможность остановиться.' },
  { text: 'Сценарий «встреча после разлуки»', desc: 'Разыграйте возвращение после долгого отсутствия, уделив внимание взглядам, объятиям и постепенному сближению.' },
  { text: 'Вечер без визуального контакта', desc: 'На короткий этап один партнёр закрывает глаза мягкой повязкой, а второй ведёт его голосом и прикосновениями, сохраняя слышимость стоп-сигнала.' },
  { text: 'Вечер с зеркалом', desc: 'Установите зеркало устойчиво и безопасно, чтобы видеть движения друг друга и обсуждать, какие ракурсы комфортны и приятны.' },
  { text: 'Эротическая игра с таймером', desc: 'Каждые десять минут меняйте формат: разговор, поцелуи, массаж, ласки или пауза на объятия, сохраняя право пропустить любой этап.' },
  { text: 'Три уровня прелюдии', desc: 'Начните с близости в одежде, при взаимном желании перейдите к частичному раздеванию и остановитесь на любом комфортном этапе.' },
  { text: 'Сюрприз-подарок для близости', desc: 'Каждый заранее выбирает небольшой аксессуар или игрушку, объясняет свой выбор и использует подарок только при согласии партнёра.' },
  { text: 'Игра «только один тип прикосновения»', desc: 'На короткий этап разрешите только один вид контакта: поцелуи, ладони, дыхание или лёгкие касания, после чего обсудите ощущения.' },
  { text: 'Вечер открытых признаний', desc: 'По очереди расскажите о ярком воспоминании, желании и моменте, который хотелось бы повторить, не превращая разговор в обязательство.' },
  { text: 'Эротическая прогулка перед возвращением домой', desc: 'Совершите вечернюю прогулку, обменивайтесь намёками и договорённостями, а дома продолжите свидание только при взаимном желании.' },
  { text: 'Вечер парфюмерных ассоциаций', desc: 'Выберите несколько безопасных ароматов и расскажите, какие воспоминания они вызывают; не используйте запах, если он раздражает кожу или дыхательные пути.' },
  { text: 'Игра «сначала забота»', desc: 'Начните с воды, пледа, массажа плеч и спокойного разговора, а затем переходите к интимному настроению только при готовности обоих.' },
  { text: 'Совместный выбор игрушки онлайн', desc: 'Изучите варианты, материалы, функции и правила ухода, обсудите границы, а решение использовать покупку примите позже.' },
  { text: 'Вечер с одной выбранной фантазией', desc: 'Выберите одну фантазию, заранее обсудите безопасные рамки и не добавляйте другие элементы без отдельного согласия.' },
  { text: 'Сценарий «частный клуб»', desc: 'Оформите комнату как закрытый клуб для двоих с дресс-кодом, правилами входа и заранее выбранной музыкой.' },
  { text: 'Эротический обмен записками', desc: 'В течение вечера оставляйте друг другу короткие записки с комплиментами, желаниями и предложениями, на которые можно ответить согласием или отказом.' },
  { text: 'Игра «партнёр выбирает музыку»', desc: 'Один партнёр управляет плейлистом, а второй подстраивает движения и настроение под композиции только в комфортном для себя темпе.' },
  { text: 'Сенсорный маршрут с повязкой', desc: 'Составьте короткий безопасный маршрут по комнате, где партнёр с закрытыми глазами получает тактильные подсказки и может остановиться в любой момент.' },
  { text: 'Эротическое меню напитков', desc: 'Подготовьте безалкогольные или алкогольные напитки, но не связывайте их с обязательными действиями и помните, что согласие требует ясного сознания.' },
  { text: 'Вечер «без цели закончить»', desc: 'Договоритесь не стремиться к оргазму или определённому финалу, а сосредоточиться на ощущениях, разговоре и близости.' },
  { text: 'Совместный разбор желаний после игры', desc: 'После вечера обсудите, что понравилось, что удивило, что стоит повторить и какие границы нужно учитывать в следующий раз.' },
];
